// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Enroll Exchange a one-time enrollment code for an agent token
	// (POST /enroll)
	Enroll(ctx context.Context, request EnrollRequestObject) (EnrollResponseObject, error)
	// ListGrants This agent's grants
	// (GET /grants)
	ListGrants(ctx context.Context, request ListGrantsRequestObject) (ListGrantsResponseObject, error)
	// CreateGrant Request access to a host
	// (POST /grants)
	CreateGrant(ctx context.Context, request CreateGrantRequestObject) (CreateGrantResponseObject, error)
	// GetGrant Get a grant, optionally long-polling for a change
	// (GET /grants/{id})
	GetGrant(ctx context.Context, request GetGrantRequestObject) (GetGrantResponseObject, error)
	// ClaimGrant Claim an admin offer with a fresh key
	// (POST /grants/{id}/claim)
	ClaimGrant(ctx context.Context, request ClaimGrantRequestObject) (ClaimGrantResponseObject, error)
	// ConnectGrant Report a command and fetch the current certificate (before every `lor ssh`)
	// (POST /grants/{id}/connect)
	ConnectGrant(ctx context.Context, request ConnectGrantRequestObject) (ConnectGrantResponseObject, error)
	// ExtendGrant Ask for more time on an active grant
	// (POST /grants/{id}/extend)
	ExtendGrant(ctx context.Context, request ExtendGrantRequestObject) (ExtendGrantResponseObject, error)
	// ReleaseGrant Give up an active grant
	// (POST /grants/{id}/release)
	ReleaseGrant(ctx context.Context, request ReleaseGrantRequestObject) (ReleaseGrantResponseObject, error)
	// ListHosts Requestable hosts
	// (GET /hosts)
	ListHosts(ctx context.Context, request ListHostsRequestObject) (ListHostsResponseObject, error)

	// (GET /whoami)
	Whoami(ctx context.Context, request WhoamiRequestObject) (WhoamiResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Enroll operation middleware
func (sh *strictHandler) Enroll(w http.ResponseWriter, r *http.Request) {
	var request EnrollRequestObject

	var body EnrollJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Enroll(ctx, request.(EnrollRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Enroll")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(EnrollResponseObject); ok {
		if err := validResponse.VisitEnrollResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

